INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Europäische Sozialcharta ein Gesetz der EU?', 2, '[{"text": "Nein", "correct": true, "because": "Europarat, nicht EU"}, {"text": "Ja", "correct": false, "because": "Falsche Institution"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt die Europäische Sozialcharta?', 3, '[{"text": "Schutz sozialer Rechte", "correct": true, "because": "Grundrechte sichern"}, {"text": "Wirtschaftswachstum", "correct": false, "because": "Nicht primär"}, {"text": "Technische Standards", "correct": false, "because": "Kein IT-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte schützt die Europäische Sozialcharta?', 5, '[{"text": "Recht auf Arbeit", "correct": true, "because": "Arbeitsbedingungen"}, {"text": "Soziale Sicherheit", "correct": true, "because": "Sozialschutz"}, {"text": "Technologiefreiheit", "correct": false, "because": "Kein ESC-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die ESC trat 1965 in Kraft. b) Sie gilt nur für EU-Mitgliedsstaaten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Europarat, nicht nur EU"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Europäischen Sozialcharta?', 4, '[{"text": "Soziale Rechte", "correct": false, "because": "Kerninhalt"}, {"text": "Überwachung", "correct": false, "because": "Ausschuss prüft"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die ESC 1996 überarbeitet wurde?', 2, '[{"text": "Ja", "correct": true, "because": "Revidierte Fassung"}, {"text": "Nein", "correct": false, "because": "Überarbeitung 1996"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gremium überwacht die ESC?', 3, '[{"text": "Europäischer Ausschuss für soziale Rechte", "correct": true, "because": "ECSR prüft"}, {"text": "Europäischer Gerichtshof", "correct": false, "because": "EU-Institution"}, {"text": "IHK", "correct": false, "because": "Kein ESC-Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten haben Staaten unter der ESC?', 5, '[{"text": "Berichte einreichen", "correct": true, "because": "Überwachung"}, {"text": "Soziale Rechte umsetzen", "correct": true, "because": "Verpflichtung"}, {"text": "Technologie fördern", "correct": false, "because": "Kein ESC-Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die ESC schützt Arbeitsrechte. b) Sie ist für Einzelklagen nutzbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine subjektiven Rechte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die ESC?', 4, '[{"text": "Ratifizierung", "correct": false, "because": "Staatenverpflichtung"}, {"text": "Berichterstattung", "correct": false, "because": "Überwachung"}, {"text": "Papierarchiv", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die ESC für alle Europaratsmitglieder verbindlich?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Ratifizierungsstaaten"}, {"text": "Ja", "correct": false, "because": "Freiwillig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte wurden 1996 in der revidierten ESC ergänzt?', 4, '[{"text": "Schutz vor Armut", "correct": true, "because": "Neuer Fokus"}, {"text": "Recht auf Wohnung", "correct": true, "because": "Erweitert"}, {"text": "Technologiefreiheit", "correct": false, "because": "Kein ESC-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die ESC keine Sanktionen vorsieht. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Nur Empfehlungen"}, {"text": "Nein", "correct": false, "because": "Keine direkten Sanktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der ESC?', 3, '[{"text": "Soziale Rechte", "correct": true, "because": "Kernziel"}, {"text": "Papierformate", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Umsetzung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die ESC wurde vom Europarat initiiert. b) Sie ist ein EU-Vertrag.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Europarat, nicht EU"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche deckt die ESC ab?', 5, '[{"text": "Arbeit", "correct": true, "because": "Arbeitsrechte"}, {"text": "Gesundheit", "correct": true, "because": "Sozialschutz"}, {"text": "Technologie", "correct": false, "because": "Kein ESC-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der ESC unwichtig?', 3, '[{"text": "Sozialpolitik", "correct": false, "because": "Kernbereich"}, {"text": "Berichterstattung", "correct": false, "because": "Überwachung"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat Deutschland die revidierte ESC ratifiziert?', 3, '[{"text": "Ja", "correct": true, "because": "2021 in Kraft"}, {"text": "Nein", "correct": false, "because": "Ratifiziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die ESC subjektive Klagen erlaubt?', 2, '[{"text": "Nein", "correct": true, "because": "Kollektivbeschwerden"}, {"text": "Ja", "correct": false, "because": "Keine Einzelklagen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für die ESC zentral?', 4, '[{"text": "Soziale Grundrechte", "correct": true, "because": "Kernprinzip"}, {"text": "Technische Standards", "correct": false, "because": "Nicht ESC"}, {"text": "Papierprozesse", "correct": false, "because": "Irrelevant"}]');
